const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.2",
  "engineVersion": "94a226be1cf2967af2541cca5529f0f7ba866919",
  "activeProvider": "postgresql",
  "inlineSchema": "model AuditLog {\n  id              String        @id @default(cuid())\n  establishmentId String\n  actorId         String?\n  actorName       String?\n  actorType       ActorType\n  action          LogAction\n  resource        String\n  resourceId      String?\n  changes         Json?\n  metadata        Json?\n  ipAddress       String?\n  userAgent       String?\n  createdAt       DateTime      @default(now())\n  establishment   Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@index([establishmentId, createdAt])\n  @@index([actorId])\n  @@index([action])\n  @@index([resource])\n  @@map(\"audit_logs\")\n}\n\nenum ActorType {\n  USER\n  EMPLOYEE\n  SYSTEM\n  GUEST\n  OWNER\n}\n\nenum LogAction {\n  CREATE\n  UPDATE\n  DELETE\n  LOGIN\n  LOGOUT\n  EXPORT\n  IMPORT\n}\n\nmodel BookingRules {\n  id                  String        @id @default(ulid())\n  minDaysInAdvance    Int           @default(0)\n  maxDaysInAdvance    Int           @default(90)\n  minGuestsPerBooking Int           @default(1)\n  maxGuestsPerBooking Int           @default(10)\n  defaultDuration     Int           @default(120)\n  autoConfirm         Boolean       @default(true)\n  allowCancellation   Boolean       @default(true)\n  cancellationHours   Int           @default(24)\n  createdAt           DateTime      @default(now())\n  updatedAt           DateTime      @updatedAt\n  establishmentId     String        @unique\n  establishment       Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@index([establishmentId])\n}\n\nmodel EstablishmentAvailability {\n  id              String                 @id @default(ulid())\n  availableDate   DateTime               @db.Date\n  isClosed        Boolean                @default(false)\n  closureReason   String?\n  createdAt       DateTime               @default(now())\n  updatedAt       DateTime               @updatedAt\n  establishmentId String\n  timeSlots       AvailabilityTimeSlot[]\n  establishment   Establishment          @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@unique([establishmentId, availableDate])\n  @@index([establishmentId])\n  @@index([availableDate])\n}\n\nmodel AvailabilityTimeSlot {\n  id             String                    @id @default(ulid())\n  slot           String\n  maxBookings    Int                       @default(10)\n  isActive       Boolean                   @default(true)\n  createdAt      DateTime                  @default(now())\n  updatedAt      DateTime                  @updatedAt\n  availabilityId String\n  availability   EstablishmentAvailability @relation(fields: [availabilityId], references: [id], onDelete: Cascade)\n  bookings       Booking[]\n\n  @@unique([availabilityId, slot])\n  @@index([availabilityId])\n}\n\nmodel Booking {\n  id                 String               @id @default(ulid())\n  bookingDate        DateTime             @db.Date\n  bookingTime        String\n  numberOfGuests     Int\n  customerName       String\n  customerEmail      String\n  customerPhone      String?\n  specialRequests    String?\n  status             BookingStatus        @default(PENDING)\n  confirmationCode   String               @unique @default(ulid())\n  createdAt          DateTime             @default(now())\n  updatedAt          DateTime             @updatedAt\n  cancelledAt        DateTime?\n  cancellationReason String?\n  userId             String?\n  establishmentId    String\n  timeSlotId         String\n  internalNotes      String?\n  source             BookingSource        @default(ONLINE)\n  establishment      Establishment        @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n  timeSlot           AvailabilityTimeSlot @relation(fields: [timeSlotId], references: [id], onDelete: Cascade)\n  user               User?                @relation(fields: [userId], references: [id])\n  logs               BookingLog[]\n\n  @@index([userId])\n  @@index([establishmentId])\n  @@index([bookingDate])\n  @@index([status])\n  @@index([confirmationCode])\n  @@index([customerEmail])\n}\n\nmodel BookingLog {\n  id          String           @id @default(ulid())\n  bookingId   String\n  event       BookingEventType\n  actorId     String?\n  actorName   String?\n  actorType   ActorType\n  description String\n  metadata    Json?\n  createdAt   DateTime         @default(now())\n  booking     Booking          @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  @@index([bookingId, createdAt])\n  @@index([bookingId, event])\n  @@map(\"booking_logs\")\n}\n\nenum BookingEventType {\n  CREATED\n  UPDATED\n  STATUS_CHANGED\n  EMAIL_SENT\n  CANCELLED\n  CONFIRMED\n  COMPLETED\n  NO_SHOW\n  NOTE_UPDATED\n  DELETED\n}\n\nenum BookingSource {\n  ONLINE\n  PHONE\n  WALK_IN\n  STAFF\n}\n\n/// =======================================================\n/// DISCOUNTS (Redução direta de preço)\n/// =======================================================\nmodel Discount {\n  id              String       @id @default(ulid())\n  establishmentId String\n  scheduleId      String?      @unique\n  name            String\n  description     String?\n  type            DiscountType\n  value           Decimal      @db.Decimal(10, 2)\n  isActive        Boolean      @default(true)\n  stackable       Boolean      @default(false)\n  startsAt        DateTime?\n  endsAt          DateTime?\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n\n  establishment Establishment    @relation(fields: [establishmentId], references: [id])\n  schedule      Schedule?        @relation(fields: [scheduleId], references: [id], onDelete: SetNull)\n  targets       DiscountTarget[]\n\n  @@index([establishmentId, isActive])\n  @@index([scheduleId])\n}\n\nenum DiscountType {\n  PERCENTAGE\n  FIXED_AMOUNT\n}\n\nmodel DiscountTarget {\n  id            String  @id @default(ulid())\n  discountId    String\n  itemId        String?\n  posCategoryId String?\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n  item     Item?    @relation(fields: [itemId], references: [id])\n\n  @@index([discountId])\n}\n\n/// =======================================================\n/// PROMOTIONS (Regras condicionais, ex: Buy X Get Y)\n/// =======================================================\nmodel Promotion {\n  id              String        @id @default(ulid())\n  establishmentId String\n  scheduleId      String?       @unique\n  name            String\n  description     String?\n  type            PromotionType\n  isActive        Boolean       @default(true)\n  startsAt        DateTime?\n  endsAt          DateTime?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  establishment Establishment @relation(fields: [establishmentId], references: [id])\n  schedule      Schedule?     @relation(fields: [scheduleId], references: [id], onDelete: SetNull)\n  buyXGetYRule  BuyXGetYRule?\n\n  @@index([establishmentId, isActive])\n  @@index([scheduleId])\n}\n\nenum PromotionType {\n  BUY_X_GET_Y\n  // futuro: SPEND_X_GET_Y, BUNDLE, FREE_DELIVERY\n}\n\n/// Regras de Buy X Get Y (aplicado ao nível de Item)\nmodel BuyXGetYRule {\n  id          String @id @default(ulid())\n  promotionId String @unique\n\n  requiredItemId   String\n  requiredQuantity Int\n\n  rewardItemId   String\n  rewardQuantity Int\n  applyCheapest  Boolean @default(true) // aplica reward no item de menor valor\n\n  promotion    Promotion @relation(fields: [promotionId], references: [id], onDelete: Cascade)\n  requiredItem Item      @relation(\"RequiredItem\", fields: [requiredItemId], references: [id])\n  rewardItem   Item      @relation(\"RewardItem\", fields: [rewardItemId], references: [id])\n}\n\nmodel EmailLog {\n  id                 String        @id\n  establishmentId    String\n  userId             String?\n  to                 String\n  template           EmailTemplate\n  type               EmailLogType  @default(TRANSACTIONAL)\n  lang               String        @db.VarChar(5)\n  subject            String\n  status             EmailStatus   @default(QUEUED)\n  provider           EmailProvider @default(ZEPTO)\n  providerMessageId  String?       @unique\n  providerStatusCode Int?\n  providerMessage    String?\n  attempts           Int           @default(0)\n  context            Json?\n  hasAttachments     Boolean       @default(false)\n  attachmentsCount   Int           @default(0)\n  queuedAt           DateTime      @default(now())\n  sentAt             DateTime?\n  deliveredAt        DateTime?\n  openedAt           DateTime?\n  clickedAt          DateTime?\n  bouncedAt          DateTime?\n  complainedAt       DateTime?\n  failedAt           DateTime?\n  metadata           Json?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime\n  emailEvents        EmailEvent[]\n  Establishment      Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@index([establishmentId, type, createdAt, status])\n  @@index([establishmentId, createdAt])\n  @@index([establishmentId, status])\n  @@index([establishmentId, template])\n  @@index([providerMessageId])\n  @@index([status, createdAt])\n  @@index([template, type])\n  @@index([to])\n  @@index([userId])\n  @@index([createdAt])\n}\n\nmodel EmailEvent {\n  id         String         @id @default(ulid())\n  emailLogId String\n  event      EmailEventType\n  occurredAt DateTime       @default(now())\n  /// Payload bruto do webhook para debugging\n  payload    Json?\n  emailLog   EmailLog       @relation(fields: [emailLogId], references: [id], onDelete: Cascade)\n\n  @@index([emailLogId])\n  @@index([emailLogId, event])\n  @@index([occurredAt])\n}\n\nenum EmailTemplate {\n  WELCOME\n  CREATE_ESTABLISHMENT\n  INVITE_EMPLOYEE\n  QRCODES\n  CREATE_BOOKING\n  CONFIRM_BOOKING\n  CANCEL_BOOKING\n  BOOKING_RECEIVED\n  BOOKING_CANCELLED\n  SUBSCRIPTION_ACTIVATED\n  SUBSCRIPTION_REACTIVATED\n  SUBSCRIPTION_CANCELED\n  SUBSCRIPTION_PAST_DUE\n  SUBSCRIPTION_TRIAL_STARTED\n  SUBSCRIPTION_TRIAL_ENDED\n  TRIAL_ENDING\n  PLAN_CHANGED\n  INVOICE_PAID\n  INVOICE_FAILED\n  PAYMENT_SUCCEEDED\n  PAYMENT_FAILED\n  UPDATE_BOOKING\n}\n\nenum EmailStatus {\n  /// Na fila BullMQ, ainda não processado\n  QUEUED\n  /// A ser processado pelo worker\n  PROCESSING\n  /// Aceite pelo provider (request 200)\n  SENT\n  /// Confirmado pelo provider via webhook\n  DELIVERED\n  /// Email aberto pelo destinatário\n  OPENED\n  /// Link clicado pelo destinatário\n  CLICKED\n  /// Bounce (hard ou soft)\n  BOUNCED\n  /// Marcado como spam\n  COMPLAINED\n  /// Erro irrecuperável\n  FAILED\n}\n\nenum EmailProvider {\n  ZEPTO\n  RESEND\n  SENDGRID\n  SES\n}\n\nenum EmailEventType {\n  QUEUED\n  PROCESSING\n  SENT\n  DELIVERED\n  OPENED\n  CLICKED\n  BOUNCED\n  COMPLAINED\n  FAILED\n  RETRY\n}\n\nenum EmailLogType {\n  SYSTEM\n  TRANSACTIONAL\n}\n\nmodel Employee {\n  id                    String        @id @default(ulid())\n  email                 String        @unique\n  authCode              Int\n  firstName             String\n  lastName              String\n  role                  EmployeeRoles\n  isActive              Boolean       @default(true)\n  createdAt             DateTime      @default(now())\n  updatedAt             DateTime      @updatedAt\n  refreshTokenHash      String?\n  refreshTokenExpiresAt DateTime?\n  establishmentId       String\n  establishment         Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@index([establishmentId, role])\n}\n\nenum EmployeeRoles {\n  MANAGER\n  KITCHEN\n  WAITER\n  CHECKOUT\n}\n\nenum ScheduleType {\n  ESTABLISHMENT\n  MENU\n  DISCOUNT\n  PROMOTION\n}\n\nenum EstablishmentLanguage {\n  PT\n  EN\n  ES\n  FR\n  DE\n  IT\n}\n\nenum EstablishmentStatus {\n  ACTIVE\n  PAYMENT_PENDING\n  INACTIVE\n  SUSPENDED\n}\n\nenum EstablishmentType {\n  RESTAURANT\n  COFFEE\n  HOTEL\n  BAR\n  CATERING\n  CASINO\n  DISCO\n  CLUB\n  ARENA\n  CINEMA\n  LOUNGE\n  RESORT\n  MOTEL\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  PAST_DUE\n  CANCELED\n  INCOMPLETE\n  INCOMPLETE_EXPIRED\n  TRIALING\n}\n\nenum BillingCycle {\n  MONTHLY\n  TIMESTRAL\n  YEARLY\n}\n\nenum FeatureType {\n  BOOLEAN\n  QUANTITY\n}\n\nenum DayOfWeek {\n  MONDAY\n  TUESDAY\n  WEDNESDAY\n  THURSDAY\n  FRIDAY\n  SATURDAY\n  SUNDAY\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  CANCELLED\n  COMPLETED\n  NO_SHOW\n}\n\nenum ServicePointType {\n  TABLE\n  BOOTH\n  COUNTER\n  ROOM\n  SUNBED\n  GENERAL\n  TERRACE\n  SUITE\n  POOL_SIDE\n  CABANA\n  SEAT\n  SECTOR\n  VIP_BOX\n  STANDING_TABLE\n  LOUNGE_AREA\n  PICKUP_POINT\n  PARKING_SPOT\n  KITCHEN\n  OBSTACLE\n  BEDROOM\n}\n\n// ─────────────────────────────────────────────────────────\n// STOCK MANAGEMENT ENUMS\n// ─────────────────────────────────────────────────────────\n\nenum StockUnit {\n  UNIT\n  KG\n  GRAM\n  LITRE\n  ML\n  CL\n  PACK\n  BOX\n  BOTTLE\n  CAN\n  BAG\n  PORTION\n  DOSE\n  SHEET\n  METER\n  CM\n}\n\nenum StockStorageTemp {\n  AMBIENT // temperatura ambiente\n  REFRIGERATED // refrigerado (0-8°C)\n  FROZEN // congelado (<-18°C)\n  CONTROLLED // temperatura controlada (8-15°C)\n}\n\nenum StockBatchStatus {\n  ACTIVE\n  DEPLETED // esgotado\n  EXPIRED // expirado\n  QUARANTINE // em quarentena\n  RECALLED // recolhido\n}\n\nenum StockEntryType {\n  PURCHASE // compra a fornecedor\n  RECEPTION // receção de encomenda pendente\n  RETURN_FROM_CLIENT // devolução de cliente\n  INITIAL_STOCK // stock inicial / abertura\n  TRANSFER_IN // transferência entrada\n  ADJUSTMENT_IN // ajuste positivo manual\n}\n\nenum StockEntryStatus {\n  DRAFT // rascunho\n  ORDERED // encomendado\n  PARTIAL // receção parcial\n  RECEIVED // rececionado\n  CANCELLED // cancelado\n  APPROVED // aprovado\n}\n\nenum StockExitType {\n  CONSUMPTION // consumo interno / produção\n  SALE // venda direta\n  WASTE // desperdício / quebra\n  RETURN_TO_SUPPLIER // devolução a fornecedor\n  TRANSFER_OUT // transferência saída\n  ADJUSTMENT_OUT // ajuste negativo manual\n  SAMPLE // amostra\n}\n\nenum StockExitStatus {\n  DRAFT\n  PENDING\n  COMPLETED\n  CANCELLED\n}\n\nenum StockMovementType {\n  PURCHASE\n  RECEPTION\n  CONSUMPTION\n  SALE\n  WASTE\n  RETURN_IN\n  RETURN_OUT\n  TRANSFER_IN\n  TRANSFER_OUT\n  ADJUSTMENT_IN\n  ADJUSTMENT_OUT\n  INVENTORY_CORRECTION\n  INITIAL_STOCK\n}\n\nenum StockMovementDir {\n  IN\n  OUT\n}\n\nenum StockAlertType {\n  LOW_STOCK // stock abaixo do mínimo\n  OUT_OF_STOCK // sem stock\n  EXPIRING_SOON // validade a expirar em breve\n  EXPIRED // validade expirada\n  OVERSTOCK // stock acima do máximo\n  REORDER_POINT // atingiu ponto de reposição\n}\n\nenum StockAlertStatus {\n  ACTIVE\n  ACKNOWLEDGED // reconhecida\n  RESOLVED\n  DISMISSED // ignorada\n}\n\nenum StockInventoryStatus {\n  DRAFT\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\nmodel Establishment {\n  // ─── Identificação ─────────────────────────────────────────────────────────\n  id       String              @id @default(ulid())\n  name     String\n  slug     String              @unique\n  type     EstablishmentType\n  status   EstablishmentStatus @default(ACTIVE)\n  isOnline Boolean             @default(false)\n\n  // ─── Contactos & Localização ────────────────────────────────────────────────\n  email       String\n  countryCode String //Calling code\n  phoneNumber String\n  address     String?\n  city        String?\n  state       String?\n  zipCode     String?\n  country     String? //NOT ISO country name\n\n  // ─── Detalhes & Faturação ──────────────────────────────────────────────────\n  billingName    String\n  billingTaxId   String\n  billingAddress String?\n  billingCity    String?\n  billingState   String?\n  billingZipCode String?\n  billingCountry String? //ISO\n\n  stripeCustomerId String @unique\n\n  // ─── Social Media ──────────────────────────────────────────────────────────\n  instagramUrl    String?\n  tiktokUrl       String?\n  facebookUrl     String?\n  googleReviewUrl String?\n  tripAdvisorUrl  String?\n  websiteUrl      String?\n\n  // ─── Configurações de Módulos ──────────────────────────────────────────────\n  myPageModule       Boolean @default(false)\n  menusModule        Boolean @default(false)\n  callStaffModule    Boolean @default(false)\n  takeAwayModule     Boolean @default(false)\n  reservationsModule Boolean @default(false)\n\n  // ─── Configurações ─────────────────────────────────────────────────────────\n  isDemo             Boolean                 @default(false)\n  primaryLanguage    EstablishmentLanguage   @default(PT)\n  availableLanguages EstablishmentLanguage[] @default([PT])\n  currency           Currency                @default(EUR)\n  timezone           String                  @default(\"Europe/Lisbon\")\n\n  wifiSsid          String?\n  wifiPassword      String?\n  googleAnalyticsId String?\n\n  // ─── Branding & Visuals ────────────────────────────────────────────────────\n  logoImageId   String?\n  bannerImageId String?\n  activeThemeId String?\n\n  // ─── Schedule ───────────────────────────────────────────────────────────────\n  scheduleId String?   @unique\n  schedule   Schedule? @relation(fields: [scheduleId], references: [id], onDelete: SetNull)\n\n  // ─── Branding & SEO ────────────────────────────────────────────────────────\n  metadata EstablishmentMetadata?\n  favicons FaviconAsset[]\n\n  // ─── Sistema ───────────────────────────────────────────────────────────────\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  ownerId   String\n\n  // ─── Relações: Core ────────────────────────────────────────────────────────\n  owner       User   @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  activeTheme Theme? @relation(\"ActiveTheme\", fields: [activeThemeId], references: [id])\n  logoImage   Image? @relation(\"LogoImage\", fields: [logoImageId], references: [id])\n  bannerImage Image? @relation(\"BannerImage\", fields: [bannerImageId], references: [id])\n\n  // ─── Relações: Módulos & Features ──────────────────────────────────────────\n  expenses       Expense[]\n  images         Image[]\n  themes         Theme[]\n  employees      Employee[]\n  serviceZones   ServiceZone[]\n  qrCodes        QrCode[]\n  menus          Menu[]\n  Item           Item[]\n  addons         Addon[]\n  variantOptions VariantOption[]\n\n  // ─── Relações: Reservas & Horários ─────────────────────────────────────────\n  bookings                     Booking[]\n  bookingRules                 BookingRules?\n  establishmentBookingSettings EstablishmentBookingSettings?\n  establishmentAvailabilities  EstablishmentAvailability[]\n\n  // ─── Relações: Integrações & Pagamentos ────────────────────────────────────\n  integrations  EstablishmentIntegrations?\n  subscription  Subscription?\n  invoices      Invoice[]\n  devices       Device[]\n  vivaTerminals VivaTerminal[]\n  sumupReaders  SumupReader[]\n\n  // ─── Relações: Marketing & Logs ────────────────────────────────────────────\n  emailLogs  EmailLog[]\n  auditLogs  AuditLog[]\n  discounts  Discount[]\n  promotions Promotion[]\n\n  // ─── Stock Management ──────────────────────────────────────────────────────\n  suppliers            Supplier[]\n  stockCategories      StockCategory[]\n  stockItems           StockItem[]\n  stockEntries         StockEntry[]\n  stockExits           StockExit[]\n  stockMovements       StockMovement[]\n  stockAlerts          StockAlert[]\n  stockInventoryCounts StockInventoryCount[]\n  stockWarehouses      StockWarehouse[]\n\n  @@index([name])\n  @@index([ownerId])\n  @@index([scheduleId])\n}\n\nenum Currency {\n  EUR\n  USD\n  GBP\n  JPY\n  CHF\n  AED\n  CNY\n}\n\nmodel EstablishmentBookingSettings {\n  id                String        @id @default(ulid())\n  enabled           Boolean       @default(false)\n  themeName         String        @default(\"default\")\n  themeMode         String        @default(\"light\")\n  establishmentId   String        @unique\n  createdAt         DateTime      @default(now())\n  notificationEmail String?\n  notificationPhone String?\n  primaryColor      String        @default(\"#f97316\")\n  updatedAt         DateTime      @updatedAt\n  establishment     Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n}\n\nmodel EstablishmentMetadata {\n  id String @id @default(ulid())\n\n  // SEO & Web Presence\n  title       String? // Título\n  shortName   String?\n  description String?\n\n  // Imagem de partilha (Open Graph)\n  ogImageId String? @unique\n  ogImage   Image?  @relation(\"OGImage\", fields: [ogImageId], references: [id])\n\n  establishmentId String        @unique\n  establishment   Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  updatedAt DateTime @updatedAt\n}\n\nmodel FaviconAsset {\n  id              String @id @default(ulid())\n  establishmentId String\n  imageId         String @unique // Um asset de favicon aponta para uma imagem única\n  role            String // Ex: 'favicon-32x32.png'\n\n  establishment Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n  image         Image         @relation(\"FaviconAsset\", fields: [imageId], references: [id], onDelete: Cascade)\n\n  @@unique([establishmentId, role]) // Um asset de favicon aponta para uma imagem única\n  @@index([establishmentId])\n}\n\nmodel Expense {\n  id            String  @id @default(cuid())\n  issuerTaxId   String\n  customerTaxId String?\n  country       String?\n\n  documentType  String\n  status        String\n  documentDate  DateTime\n  invoiceNumber String\n\n  totalAmount Float\n  taxableBase Float\n  taxAmount   Float\n\n  atcud        String?\n  controlCode  String?\n  documentHash String?\n  certificate  String?\n\n  establishmentId String\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  rawData Json?\n\n  establishment Establishment? @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n}\n\nmodel Image {\n  id                      String                 @id @default(ulid())\n  cloudflareImageId       String                 @unique\n  fileName                String\n  url                     String\n  fileSize                Float\n  metadata                Json?\n  establishmentId         String\n  createdAt               DateTime               @default(now())\n  updatedAt               DateTime               @updatedAt\n  bannerUsedInBrands      Establishment[]        @relation(\"BannerImage\")\n  logoUsedInBrands        Establishment[]        @relation(\"LogoImage\")\n  establishment           Establishment          @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n  item                    Item[]                 @relation(\"ImageItem\")\n  itemVariants            ItemVariant[]          @relation(\"ItemVariantImage\")\n  menuCategory            MenuCategory[]         @relation(\"ImageMenuCategory\")\n  establishmentMetadataOg EstablishmentMetadata? @relation(\"OGImage\")\n  faviconAssets           FaviconAsset[]         @relation(\"FaviconAsset\")\n\n  @@index([establishmentId])\n}\n\n/// Stores all third-party integration credentials and toggle states for an establishment.\n/// All sensitive values (API keys, secrets) are stored AES-256 encrypted.\n/// The `*Enabled` flags control whether the integration is actively used at runtime,\n/// independently of whether credentials are present.\nmodel EstablishmentIntegrations {\n  id              String   @id @default(ulid())\n  establishmentId String   @unique\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  // ─── EuPago ───────────────────────────────────────────────────────────────\n  // Payment gateway: Multibanco, MB WAY, Visa/Mastercard.\n  // eupagoApiKey    — encrypted EuPago API key\n  // eupagoCryptoKey — optional encryption key for MB WAY payloads\n  eupagoEnabled   Boolean @default(false)\n  eupagoApiKey    String?\n  eupagoCryptoKey String?\n\n  // ─── Biziq ────────────────────────────────────────────────────────────────\n  // Portuguese e-invoicing platform (AT / SAF-T compliant).\n  // biziqAccountId  — encrypted Biziq account identifier\n  // biziqApiKey     — encrypted Biziq API key\n  // biziqCompanyVat — optional encrypted company VAT for invoice issuer data\n  biziqEnabled    Boolean @default(false)\n  biziqAccountId  String?\n  biziqApiKey     String?\n  biziqCompanyVat String?\n\n  // ─── Viva Wallet EFT-POS ──────────────────────────────────────────────────\n  // Physical card terminal integration via REST EFT-POS API (OAuth2).\n  // vivaClientId     — encrypted OAuth2 client ID\n  // vivaClientSecret — encrypted OAuth2 client secret\n  vivaEnabled      Boolean @default(false)\n  vivaClientId     String?\n  vivaClientSecret String?\n\n  // ─── SumUp Cloud API ──────────────────────────────────────────────────────────\n  // Solo card reader integration via HTTPS Cloud API.\n  // sumupApiKey       — encrypted Bearer token (Personal API Key or OAuth2)\n  // sumupMerchantCode — encrypted merchant account code (required for reader endpoints)\n  sumupEnabled      Boolean @default(false)\n  sumupApiKey       String?\n  sumupMerchantCode String?\n\n  // ─── Vendus ───────────────────────────────────────────────────────────────\n  // Portuguese fiscal invoicing platform (Faturas, Recibos, etc.).\n  // vendusApiKey — encrypted Vendus API key (Bearer token for all requests)\n  vendusEnabled Boolean @default(false)\n  vendusApiKey  String?\n\n  establishment Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n}\n\n// ─── SumUp Solo Reader ────────────────────────────────────────────────────────\n// Represents a Solo card reader paired to an establishment via the Cloud API.\n// readerId   — SumUp reader ID returned after pairing (used for checkouts)\n// name       — human-readable label set by the operator (e.g. \"Caixa 1\")\n// deviceId   — physical device identifier (optional, from SumUp response)\nmodel SumupReader {\n  id              String        @id @default(ulid())\n  establishmentId String\n  readerId        String // SumUp Cloud API reader identifier\n  name            String? // operator label, e.g. \"Balcão Principal\"\n  deviceId        String? // physical device id from SumUp\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n  establishment   Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@unique([establishmentId, readerId])\n}\n\n// ─── Viva Wallet Physical Terminal ────────────────────────────────────────────\n// Represents a card terminal (POS) registered for an establishment.\n// terminalId  — the Viva terminal serial/identifier (from their dashboard)\n// posId       — the numeric POS id returned by Viva's API when the terminal is registered\n// alias       — a human-readable label set by the operator (e.g. \"Caixa 1\")\nmodel VivaTerminal {\n  id              String        @id @default(ulid())\n  establishmentId String\n  terminalId      String // Viva terminal serial number / identifier\n  alias           String? // operator label, e.g. \"Caixa 1\"\n  posId           String? // Viva POS id (returned after registration, used for payments)\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n  establishment   Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@unique([establishmentId, terminalId])\n}\n\n/// =======================================================\n/// 1. ITEM (Produto Pai / Raiz do Catálogo)\n/// =======================================================\nmodel Item {\n  id              String    @id @default(ulid())\n  imageId         String?\n  establishmentId String\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  /// O basePrice APENAS é usado se o item NÃO tiver variantes.\n  basePrice       Decimal?  @db.Decimal(10, 2)\n  deletedAt       DateTime?\n  posCategoryId   String?\n  sku             String?\n\n  unit     UnitType @default(UNIT)\n  quantity Float    @default(1)\n\n  status              ItemStatus           @default(ACTIVE)\n  taxTableId          String\n  allergens           ItemAllergen[]\n  establishment       Establishment        @relation(fields: [establishmentId], references: [id])\n  image               Image?               @relation(\"ImageItem\", fields: [imageId], references: [id])\n  posCategory         POSCategory?         @relation(fields: [posCategoryId], references: [id])\n  taxTable            TaxTable             @relation(fields: [taxTableId], references: [id])\n  modifierGroups      ItemModifierGroup[]\n  itemModifierOptions ItemModifierOption[]\n  translations        ItemTranslation[]\n  variants            ItemVariant[]\n  itemVariantGroups   ItemVariantGroup[]\n  menuItemPositions   MenuItemPosition[]\n  nutritionInfo       ItemNutritionInfo?\n  discounts           DiscountTarget[]\n  requiredItemRules   BuyXGetYRule[]       @relation(\"RequiredItem\")\n  rewardItemRules     BuyXGetYRule[]       @relation(\"RewardItem\")\n  marketingTag        MarketingTag?\n  spiceLevel          SpiceLevel?\n  isFeatured          Boolean              @default(false)\n  hasAlcohol          Boolean              @default(false)\n  attributes          ItemAttribute[]\n  vendusProductId     Int?\n\n  @@unique([establishmentId, sku])\n  @@index([establishmentId, status])\n  @@index([deletedAt])\n}\n\nmodel ItemNutritionInfo {\n  id            String   @id @default(ulid())\n  energyKcal    Float?\n  fat           Float?\n  saturatedFat  Float?\n  carbohydrates Float?\n  sugars        Float?\n  fiber         Float?\n  protein       Float?\n  salt          Float?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n  itemId        String?  @unique\n  item          Item?    @relation(fields: [itemId], references: [id])\n}\n\nmodel VariantNutrionalInfo {\n  id            String       @id @default(ulid())\n  energyKcal    Float?\n  fat           Float?\n  saturatedFat  Float?\n  carbohydrates Float?\n  sugars        Float?\n  fiber         Float?\n  protein       Float?\n  salt          Float?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n  itemVariantId String?      @unique\n  itemVariant   ItemVariant? @relation(fields: [itemVariantId], references: [id])\n}\n\nmodel ItemTranslation {\n  id               String  @id @default(ulid())\n  locale           String\n  name             String\n  shortDescription String?\n  description      String?\n  itemId           String\n  item             Item    @relation(fields: [itemId], references: [id], onDelete: Cascade)\n\n  @@unique([itemId, locale])\n}\n\n/// A. O Dicionário de Opções (Ex: \"Pequena\", \"Média\", \"33cl\")\nmodel VariantOption {\n  id              String                     @id @default(ulid())\n  establishmentId String?\n  isGlobal        Boolean                    @default(false)\n  code            String?                    @unique\n  isActive        Boolean                    @default(true)\n  quantity        Float?\n  unit            UnitType?\n  itemVariants    ItemVariant[]\n  establishment   Establishment?             @relation(fields: [establishmentId], references: [id])\n  translations    VariantOptionTranslation[]\n\n  @@index([establishmentId])\n}\n\nmodel VariantOptionTranslation {\n  id              String        @id @default(ulid())\n  variantOptionId String\n  locale          String\n  name            String\n  variantOption   VariantOption @relation(fields: [variantOptionId], references: [id], onDelete: Cascade)\n\n  @@unique([variantOptionId, locale])\n}\n\n/// B. O Grupo Local (Simetria perfeita com Modifiers)\n/// Ex: \"Escolha o Tamanho\"\nmodel ItemVariantGroup {\n  itemId       String\n  position     Int                           @default(0)\n  id           String                        @id @default(ulid())\n  variants     ItemVariant[]\n  item         Item                          @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  translations ItemVariantGroupTranslation[]\n\n  @@index([itemId])\n}\n\nmodel ItemVariantGroupTranslation {\n  id                 String           @id @default(ulid())\n  itemVariantGroupId String\n  locale             String\n  name               String\n  itemVariantGroup   ItemVariantGroup @relation(fields: [itemVariantGroupId], references: [id], onDelete: Cascade)\n\n  @@unique([itemVariantGroupId, locale])\n}\n\nmodel ItemVariant {\n  id                 String                @id @default(ulid())\n  itemId             String\n  price              Decimal               @db.Decimal(10, 2)\n  sku                String?\n  isDefault          Boolean               @default(false)\n  isActive           Boolean               @default(true)\n  imageId            String?\n  itemVariantGroupId String\n  position           Int                   @default(0)\n  variantOptionId    String\n  allergens          ItemVariantAllergen[]\n  modifierOptions    ItemModifierOption[]\n  image              Image?                @relation(\"ItemVariantImage\", fields: [imageId], references: [id])\n  item               Item                  @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  group              ItemVariantGroup      @relation(fields: [itemVariantGroupId], references: [id], onDelete: Cascade)\n  variantOption      VariantOption         @relation(fields: [variantOptionId], references: [id])\n  nutritionInfo      VariantNutrionalInfo?\n  deletedAt          DateTime?\n\n  @@unique([itemVariantGroupId, variantOptionId])\n  @@unique([id, sku])\n  @@index([itemId])\n  @@index([deletedAt])\n}\n\n/// A. Grupo de Modificadores (As perguntas feitas ao cliente)\nmodel ItemModifierGroup {\n  id           String                         @id @default(ulid())\n  itemId       String\n  minSelection Int                            @default(0)\n  maxSelection Int?\n  position     Int                            @default(0)\n  displayMode  ModifierDisplayMode            @default(RADIO)\n  isActive     Boolean                        @default(true)\n  item         Item                           @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  translations ItemModifierGroupTranslation[]\n  options      ItemModifierOption[]\n  deletedAt    DateTime?\n\n  @@index([deletedAt])\n}\n\nmodel ItemModifierGroupTranslation {\n  id              String            @id @default(ulid())\n  modifierGroupId String\n  locale          String\n  name            String\n  modifierGroup   ItemModifierGroup @relation(fields: [modifierGroupId], references: [id], onDelete: Cascade)\n  deletedAt       DateTime?\n\n  @@unique([modifierGroupId, locale])\n}\n\n/// B. O Dicionário de Addons Simples (Instruções de cozinha, extras)\n/// Coisas que não existem como Item (Ex: \"Massa Fina\", \"Sem Gelo\")\nmodel Addon {\n  id                  String               @id @default(ulid())\n  establishmentId     String?\n  isActive            Boolean              @default(true)\n  isGlobal            Boolean              @default(false)\n  establishment       Establishment?       @relation(fields: [establishmentId], references: [id])\n  translations        AddonTranslation[]\n  itemModifierOptions ItemModifierOption[]\n\n  @@index([establishmentId])\n  @@index([isGlobal])\n}\n\nmodel AddonTranslation {\n  id      String @id @default(ulid())\n  addonId String\n  locale  String\n  name    String\n  addon   Addon  @relation(fields: [addonId], references: [id], onDelete: Cascade)\n\n  @@unique([addonId, locale])\n}\n\nmodel Allergen {\n  id                   String                @id @default(ulid())\n  code                 AllergenCode          @unique\n  itemAllergens        ItemAllergen[]\n  itemVariantAllergens ItemVariantAllergen[]\n}\n\nmodel ItemAllergen {\n  id         String   @id @default(ulid())\n  itemId     String\n  allergenId String\n  allergen   Allergen @relation(fields: [allergenId], references: [id], onDelete: Cascade)\n  item       Item     @relation(fields: [itemId], references: [id], onDelete: Cascade)\n\n  @@unique([itemId, allergenId])\n}\n\nmodel ItemVariantAllergen {\n  id            String   @id @default(ulid())\n  itemVariantId String\n  allergenId    String\n  allergen      Allergen @relation(fields: [allergenId], references: [id], onDelete: Cascade)\n\n  itemVariant ItemVariant @relation(fields: [itemVariantId], references: [id], onDelete: Cascade)\n\n  @@unique([itemVariantId, allergenId])\n}\n\n/// C. As Opções do Modificador (Polimorfismo!)\n/// REGRA SQL (CONSTRAINT): Apenas 1 alvo pode ser preenchido (addonId, productId ou itemVariantId)\nmodel ItemModifierOption {\n  id              String            @id @default(ulid())\n  modifierGroupId String\n  price           Decimal?          @db.Decimal(10, 2)\n  position        Int               @default(0)\n  defaultQuantity Int               @default(0)\n  minQuantity     Int               @default(0)\n  maxQuantity     Int               @default(1)\n  addonId         String?\n  productId       String?\n  itemVariantId   String?\n  addon           Addon?            @relation(fields: [addonId], references: [id])\n  itemVariant     ItemVariant?      @relation(fields: [itemVariantId], references: [id])\n  group           ItemModifierGroup @relation(fields: [modifierGroupId], references: [id], onDelete: Cascade)\n  product         Item?             @relation(fields: [productId], references: [id])\n\n  @@index([modifierGroupId])\n}\n\nenum ItemStatus {\n  ACTIVE\n  DRAFT\n  INACTIVE\n}\n\nenum AllergenCode {\n  CELERY\n  CRUSTACEAN\n  EGG\n  FISH\n  GLUTEN\n  LUPINS\n  MILK\n  MUSTARD\n  NUTS\n  PEANUTS\n  SESAME\n  SHELLFISH\n  SOY\n  SULFITES\n}\n\nenum ModifierDisplayMode {\n  RADIO\n  CHECKBOX\n  QUANTITY\n}\n\nenum SpiceLevel {\n  LOW\n  MEDIUM\n  HIGH\n  EXTRA_HOT\n}\n\nmodel ItemAttribute {\n  id     String        @id @default(ulid())\n  type   AttributeType\n  itemId String\n\n  item Item @relation(fields: [itemId], references: [id], onDelete: Cascade)\n\n  @@unique([itemId, type])\n}\n\nenum AttributeType {\n  VEGAN\n  VEGETARIAN\n  GLUTEN_FREE\n  DAIRY_FREE\n  HALAL\n  KOSHER\n}\n\nenum MarketingTag {\n  BESTSELLER\n  NEW\n  POPULAR\n  LIMITED\n}\n\nenum UnitType {\n  // --- Serving ---\n  PORTION\n  HALF\n  SLICE\n  PIECE\n  PLATE\n  BOWL\n  UNIT\n\n  // --- Drinks ---\n  GLASS\n  CUP\n  SHOT\n  MUG\n\n  // --- Containers ---\n  BOTTLE\n  CAN\n\n  // --- Measurements ---\n  MILLILITER\n  CENTILITER\n  LITER\n  GRAM\n  KILOGRAM\n  OUNCE\n  POUND\n}\n\n/**\n * model ItemBundle {\n * id        String  @id @default(ulid())\n * itemId    String\n * position  Int     @default(0)\n * item      Item    @relation(fields: [itemId], references: [id], onDelete: Cascade)\n * options   ItemBundleOption[]\n * }\n * model ItemBundleOption {\n * id            String  @id @default(ulid())\n * bundleId      String\n * productId     String\n * minSelection  Int     @default(1)\n * maxSelection  Int     @default(1)\n * bundle        ItemBundle @relation(fields: [bundleId], references: [id], onDelete: Cascade)\n * product       Item       @relation(fields: [productId], references: [id])\n * }\n */\n\nmodel Menu {\n  id               String   @id @default(ulid())\n  position         Int      @default(0)\n  isVisible        Boolean  @default(false)\n  isHighlighted    Boolean  @default(false)\n  color            String?\n  establishmentId  String\n  scheduleId       String?  @unique\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n  maxItemsPerOrder Int?\n  price            Float?\n\n  showImages Boolean  @default(true)\n  type       MenuType @default(LA_CARTE)\n\n  establishment Establishment     @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n  schedule      Schedule?         @relation(fields: [scheduleId], references: [id], onDelete: SetNull)\n  categories    MenuCategory[]\n  translations  MenuTranslation[]\n\n  @@index([establishmentId])\n  @@index([establishmentId, position])\n  @@index([scheduleId])\n}\n\nmodel MenuTranslation {\n  id           String   @id @default(ulid())\n  locale       String\n  name         String\n  description  String?\n  observations String?\n  menuId       String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  menu         Menu     @relation(fields: [menuId], references: [id], onDelete: Cascade)\n\n  @@unique([menuId, locale])\n  @@index([menuId])\n}\n\nmodel MenuCategory {\n  id            String                    @id @default(ulid())\n  isVisible     Boolean                   @default(true)\n  imageId       String?\n  menuId        String\n  position      Int                       @default(0)\n  createdAt     DateTime                  @default(now())\n  updatedAt     DateTime                  @updatedAt\n  image         Image?                    @relation(\"ImageMenuCategory\", fields: [imageId], references: [id])\n  menu          Menu                      @relation(fields: [menuId], references: [id], onDelete: Cascade)\n  translations  MenuCategoryTranslation[]\n  subcategories MenuSubcategory[]\n\n  @@index([menuId])\n  @@index([menuId, position])\n}\n\nmodel MenuCategoryTranslation {\n  id         String       @id @default(ulid())\n  locale     String\n  name       String\n  categoryId String\n  createdAt  DateTime     @default(now())\n  updatedAt  DateTime     @updatedAt\n  category   MenuCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([categoryId, locale])\n}\n\nmodel MenuSubcategory {\n  id           String                       @id @default(ulid())\n  isVisible    Boolean                      @default(true)\n  categoryId   String?\n  position     Int                          @default(0)\n  createdAt    DateTime                     @default(now())\n  updatedAt    DateTime                     @updatedAt\n  items        MenuItemPosition[]\n  category     MenuCategory?                @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  translations MenuSubcategoryTranslation[]\n\n  @@index([categoryId])\n  @@index([categoryId, position])\n}\n\nmodel MenuSubcategoryTranslation {\n  id            String          @id @default(ulid())\n  locale        String\n  name          String\n  description   String?\n  subcategoryId String\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n  subcategory   MenuSubcategory @relation(fields: [subcategoryId], references: [id], onDelete: Cascade)\n\n  @@unique([subcategoryId, locale])\n}\n\nmodel MenuItemPosition {\n  id            String          @id @default(ulid())\n  itemId        String\n  subcategoryId String\n  position      Int             @default(0)\n  isVisible     Boolean         @default(true)\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n  isIncluded    Boolean         @default(false)\n  item          Item            @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  subcategory   MenuSubcategory @relation(fields: [subcategoryId], references: [id], onDelete: Cascade)\n\n  @@unique([itemId, subcategoryId])\n  @@index([itemId])\n  @@index([subcategoryId])\n  @@index([subcategoryId, position])\n}\n\nenum MenuType {\n  LA_CARTE\n  RODIZIO\n}\n\nmodel MoloniToken {\n  id               String   @id @default(cuid())\n  accessToken      String\n  refreshToken     String\n  expiresAt        DateTime\n  refreshExpiresAt DateTime\n  updatedAt        DateTime @updatedAt\n  createdAt        DateTime @default(now())\n  establishmentId  String?  @unique\n\n  @@map(\"moloni_tokens\")\n}\n\nmodel OrderItem {\n  id              String   @id @default(ulid())\n  orderId         String\n  itemId          String\n  itemVariantId   String? // se aplicável\n  quantity        Int\n  basePrice       Decimal  @db.Decimal(10, 2) // preço unitário sem promoções\n  modifierTotal   Decimal  @db.Decimal(10, 2) // total de modificadores\n  subtotal        Decimal  @db.Decimal(10, 2) // basePrice * quantity + modifiers\n  discountAmount  Decimal  @db.Decimal(10, 2) // desconto aplicado neste item\n  promotionAmount Decimal  @db.Decimal(10, 2) // recompensa/promo aplicada\n  finalPrice      Decimal  @db.Decimal(10, 2) // subtotal - discountAmount - promotionAmount\n  promotionId     String? // referência a promoção aplicada\n  discountId      String? // referência a desconto aplicado\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\n/**\n * model Order {\n * id              String         @id @default(ulid())\n * establishmentId String\n * customerName    String?\n * status          OrderStatus    @default(PENDING)\n * total           Decimal        @db.Decimal(10, 2)\n * tax             Decimal?       @db.Decimal(10, 2)\n * createdAt       DateTime       @default(now())\n * updatedAt       DateTime       @updatedAt\n * fiscalRecords   FiscalRecord[]\n * establishment   Establishment  @relation(fields: [establishmentId], references: [id])\n * items           OrderItem[]\n * payments        Payment[]\n * }\n * model OrderItem {\n * id            String              @id @default(ulid())\n * orderId       String\n * itemId        String\n * itemVariantId String?\n * quantity      Int                 @default(1)\n * unitPrice     Decimal             @db.Decimal(10, 2)\n * totalPrice    Decimal             @db.Decimal(10, 2)\n * item          Item                @relation(fields: [itemId], references: [id])\n * variant       ItemVariant?        @relation(fields: [itemVariantId], references: [id])\n * order         Order               @relation(fields: [orderId], references: [id], onDelete: Cascade)\n * modifiers     OrderItemModifier[]\n * }\n * model OrderItemModifier {\n * id               String             @id @default(ulid())\n * orderItemId      String\n * modifierOptionId String\n * quantity         Int                @default(1)\n * price            Decimal            @db.Decimal(10, 2)\n * modifierOption   ItemModifierOption @relation(fields: [modifierOptionId], references: [id])\n * orderItem        OrderItem          @relation(fields: [orderItemId], references: [id], onDelete: Cascade)\n * }\n * model Payment {\n * id        String        @id @default(ulid())\n * orderId   String\n * method    PaymentMethod\n * amount    Decimal       @db.Decimal(10, 2)\n * createdAt DateTime      @default(now())\n * order     Order         @relation(fields: [orderId], references: [id])\n * }\n * model FiscalRecord {\n * id        String       @id @default(ulid())\n * orderId   String\n * status    FiscalStatus @default(PENDING)\n * xml       String?\n * pdf       String?\n * createdAt DateTime     @default(now())\n * updatedAt DateTime     @updatedAt\n * order     Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n * }\n * enum OrderStatus {\n * PENDING\n * CONFIRMED\n * CANCELLED\n * COMPLETED\n * }\n * enum PaymentMethod {\n * CASH\n * CARD\n * DIGITAL\n * GIFT_CARD\n * }\n * enum FiscalStatus {\n * PENDING\n * SENT\n * CANCELLED\n * FAILED\n * COMPLETED\n * }\n */\n\nmodel POSCategory {\n  id              String @id @default(ulid())\n  name            String\n  establishmentId String\n  items           Item[]\n}\n\nmodel Device {\n  id              String        @id @default(ulid())\n  name            String?\n  pairingKey      String?       @unique\n  deviceToken     String?       @unique\n  isActive        Boolean       @default(false)\n  lastSeen        DateTime?\n  establishmentId String\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n  establishment   Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n  printers        Printer[]\n\n  @@map(\"devices\")\n}\n\nmodel Printer {\n  id           String   @id @default(ulid())\n  name         String\n  friendlyName String?\n  isDefault    Boolean  @default(false)\n  isEnabled    Boolean  @default(true)\n  deviceId     String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  device       Device   @relation(fields: [deviceId], references: [id], onDelete: Cascade)\n\n  @@unique([deviceId, name])\n  @@map(\"printers\")\n}\n\nmodel QrCode {\n  id              String        @id @default(ulid())\n  token           String        @unique\n  establishmentId String\n  establishment   Establishment @relation(fields: [establishmentId], references: [id])\n  servicePointId  String?\n  servicePoint    ServicePoint? @relation(fields: [servicePointId], references: [id])\n  type            QrCodeType    @default(TABLE)\n\n  active Boolean @default(true)\n  config Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nenum QrCodeType {\n  TABLE\n  MENU\n}\n\nmodel Schedule {\n  id        String       @id @default(ulid())\n  type      ScheduleType\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  // Days of the schedule (one per day of week)\n  days ScheduleDay[]\n\n  // Relations to entities that use schedules\n  establishment Establishment?\n  menus         Menu?\n  discounts     Discount?\n  promotions    Promotion?\n}\n\nmodel ScheduleDay {\n  id         String   @id @default(ulid())\n  scheduleId String\n  schedule   Schedule @relation(fields: [scheduleId], onDelete: Cascade, references: [id])\n\n  dayOfWeek DayOfWeek\n  isOpen    Boolean   @default(true)\n\n  // Time intervals for this day (e.g., 09:00-12:00, 14:00-18:00)\n  intervals TimeInterval[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Ensure each schedule has only one entry per day\n  @@unique([scheduleId, dayOfWeek])\n  @@index([scheduleId])\n}\n\nmodel TimeInterval {\n  id            String      @id @default(ulid())\n  scheduleDayId String\n  scheduleDay   ScheduleDay @relation(fields: [scheduleDayId], onDelete: Cascade, references: [id])\n\n  startTime String // Format: \"HH:mm\"\n  endTime   String // Format: \"HH:mm\"\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([scheduleDayId])\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/core\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// =======================================================\n/// STOCK MANAGEMENT SYSTEM\n/// Gestão Completa de Stock: Fornecedores, Entradas,\n/// Saídas, Lotes, Validades, Inventário, Alertas,\n/// Armazéns e Localizações\n/// =======================================================\n\n// ─────────────────────────────────────────────────────────\n// 0. WAREHOUSE (Armazéns / Espaços de Armazenamento)\n// ─────────────────────────────────────────────────────────\nmodel StockWarehouse {\n  id              String    @id @default(ulid())\n  establishmentId String\n  name            String // ex: \"Armazém Principal\", \"Câmara Fria\"\n  code            String? // código curto ex: \"ARM-01\"\n  description     String?\n  address         String?\n  isActive        Boolean   @default(true)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  deletedAt       DateTime?\n\n  establishment Establishment   @relation(fields: [establishmentId], references: [id])\n  locations     StockLocation[]\n  stockItems    StockItem[]\n\n  @@unique([establishmentId, code])\n  @@index([establishmentId, isActive])\n}\n\n// ─────────────────────────────────────────────────────────\n// 0b. STOCK LOCATION (Localizações dentro de um Armazém)\n// ─────────────────────────────────────────────────────────\nmodel StockLocation {\n  id          String   @id @default(ulid())\n  warehouseId String\n  name        String // ex: \"Prateleira A1\", \"Câmara B2\"\n  code        String? // código legível ex: \"A1-P3\"\n  aisle       String? // corredor\n  shelf       String? // prateleira\n  bin         String? // posição/bin\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  warehouse  StockWarehouse @relation(fields: [warehouseId], references: [id], onDelete: Cascade)\n  stockItems StockItem[]\n  batches    StockBatch[]\n\n  @@unique([warehouseId, code])\n  @@index([warehouseId])\n}\n\n// ─────────────────────────────────────────────────────────\n// 1. SUPPLIER (Fornecedores)\n// ─────────────────────────────────────────────────────────\nmodel Supplier {\n  id              String    @id @default(ulid())\n  establishmentId String\n  name            String\n  code            String?\n  taxId           String? // NIF / VAT Number\n  email           String?\n  phone           String?\n  website         String?\n  address         String?\n  city            String?\n  postalCode      String?\n  country         String?   @default(\"PT\")\n  contactPerson   String?\n  paymentTermDays Int?      @default(30)\n  currency        String?   @default(\"EUR\")\n  notes           String?\n  isActive        Boolean   @default(true)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  deletedAt       DateTime?\n\n  establishment Establishment       @relation(fields: [establishmentId], references: [id])\n  stockEntries  StockEntry[]\n  stockItems    StockItemSupplier[]\n\n  @@unique([establishmentId, code])\n  @@index([establishmentId, isActive])\n  @@index([establishmentId, name])\n}\n\n// ─────────────────────────────────────────────────────────\n// 2. STOCK CATEGORY (Categorias de Stock)\n// ─────────────────────────────────────────────────────────\nmodel StockCategory {\n  id              String   @id @default(ulid())\n  establishmentId String\n  name            String\n  color           String?  @default(\"#6366f1\")\n  icon            String?\n  parentId        String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  establishment Establishment   @relation(fields: [establishmentId], references: [id])\n  parent        StockCategory?  @relation(\"CategoryChildren\", fields: [parentId], references: [id])\n  children      StockCategory[] @relation(\"CategoryChildren\")\n  stockItems    StockItem[]\n\n  @@unique([establishmentId, name])\n  @@index([establishmentId])\n}\n\n// ─────────────────────────────────────────────────────────\n// 3. STOCK ITEM (Produto de Stock / Ingrediente)\n// ─────────────────────────────────────────────────────────\nmodel StockItem {\n  id              String            @id @default(ulid())\n  establishmentId String\n  categoryId      String?\n  warehouseId     String? // armazém padrão\n  locationId      String? // localização padrão (prateleira/bin)\n  name            String\n  description     String?\n  sku             String?\n  barcode         String?\n  unit            StockUnit         @default(UNIT)\n  unitWeight      Float? // peso por unidade em gramas/ml\n  currentStock    Float             @default(0)\n  reservedStock   Float             @default(0) // reservado para pedidos em aberto\n  minStockLevel   Float? // nível de alerta mínimo\n  maxStockLevel   Float? // nível máximo de encomenda\n  reorderPoint    Float? // ponto de reposição automática\n  reorderQty      Float? // quantidade sugerida de encomenda\n  averageCost     Decimal?          @db.Decimal(10, 4) // custo médio ponderado\n  lastCost        Decimal?          @db.Decimal(10, 4) // último custo de compra\n  isPerishable    Boolean           @default(false)\n  shelfLifeDays   Int? // prazo de validade padrão em dias\n  storageTemp     StockStorageTemp?\n  isActive        Boolean           @default(true)\n  isTracked       Boolean           @default(true) // se false, não controla stock\n  imageUrl        String?\n  notes           String?\n  createdAt       DateTime          @default(now())\n  updatedAt       DateTime          @updatedAt\n  deletedAt       DateTime?\n\n  establishment  Establishment             @relation(fields: [establishmentId], references: [id])\n  category       StockCategory?            @relation(fields: [categoryId], references: [id])\n  warehouse      StockWarehouse?           @relation(fields: [warehouseId], references: [id])\n  location       StockLocation?            @relation(fields: [locationId], references: [id])\n  batches        StockBatch[]\n  entryItems     StockEntryItem[]\n  exitItems      StockExitItem[]\n  movements      StockMovement[]\n  alerts         StockAlert[]\n  suppliers      StockItemSupplier[]\n  inventoryItems StockInventoryCountItem[]\n\n  @@unique([establishmentId, sku])\n  @@index([establishmentId, isActive])\n  @@index([establishmentId, categoryId])\n  @@index([establishmentId, warehouseId])\n}\n\n// ─────────────────────────────────────────────────────────\n// 4. STOCK ITEM × SUPPLIER (Relação N-N com dados extra)\n// ─────────────────────────────────────────────────────────\nmodel StockItemSupplier {\n  id                String   @id @default(ulid())\n  stockItemId       String\n  supplierId        String\n  supplierCode      String? // código do produto no fornecedor\n  lastPurchasePrice Decimal? @db.Decimal(10, 4)\n  isPreferred       Boolean  @default(false)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  stockItem StockItem @relation(fields: [stockItemId], references: [id], onDelete: Cascade)\n  supplier  Supplier  @relation(fields: [supplierId], references: [id])\n\n  @@unique([stockItemId, supplierId])\n}\n\n// ─────────────────────────────────────────────────────────\n// 5. STOCK BATCH (Lotes com Validade - Rastreabilidade)\n// ─────────────────────────────────────────────────────────\nmodel StockBatch {\n  id              String           @id @default(ulid())\n  stockItemId     String\n  locationId      String? // localização específica deste lote\n  batchNumber     String\n  lotNumber       String?\n  expiryDate      DateTime?\n  manufactureDate DateTime?\n  quantity        Float // quantidade inicial do lote\n  remainingQty    Float // quantidade restante\n  costPerUnit     Decimal?         @db.Decimal(10, 4)\n  status          StockBatchStatus @default(ACTIVE)\n  notes           String?\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  stockItem  StockItem        @relation(fields: [stockItemId], references: [id])\n  location   StockLocation?   @relation(fields: [locationId], references: [id])\n  entryItems StockEntryItem[]\n  exitItems  StockExitItem[]\n\n  @@index([stockItemId, status])\n  @@index([expiryDate])\n}\n\n// ─────────────────────────────────────────────────────────\n// 6. STOCK ENTRY (Entrada: Compra / Receção / Ajuste+)\n// ─────────────────────────────────────────────────────────\nmodel StockEntry {\n  id              String           @id @default(ulid())\n  establishmentId String\n  supplierId      String?\n  type            StockEntryType\n  status          StockEntryStatus @default(DRAFT)\n  reference       String? // número de PO / fatura\n  supplierRef     String? // referência do fornecedor\n  entryDate       DateTime         @default(now())\n  expectedDate    DateTime?\n  receivedDate    DateTime?\n  totalAmount     Decimal?         @db.Decimal(10, 2)\n  taxAmount       Decimal?         @db.Decimal(10, 2)\n  discountAmount  Decimal?         @db.Decimal(10, 2)\n  notes           String?\n  createdBy       String?\n  approvedBy      String?\n  approvedAt      DateTime?\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  establishment Establishment    @relation(fields: [establishmentId], references: [id])\n  supplier      Supplier?        @relation(fields: [supplierId], references: [id])\n  items         StockEntryItem[]\n  movements     StockMovement[]\n\n  @@index([establishmentId, status])\n  @@index([establishmentId, entryDate])\n  @@index([establishmentId, type])\n}\n\n// ─────────────────────────────────────────────────────────\n// 7. STOCK ENTRY ITEM (Linha de Entrada)\n// ─────────────────────────────────────────────────────────\nmodel StockEntryItem {\n  id           String    @id @default(ulid())\n  entryId      String\n  stockItemId  String\n  batchId      String?\n  orderedQty   Float? // quantidade encomendada\n  receivedQty  Float // quantidade recebida\n  unitCost     Decimal   @db.Decimal(10, 4)\n  totalCost    Decimal   @db.Decimal(10, 4)\n  taxRate      Decimal?  @db.Decimal(5, 2)\n  discountRate Decimal?  @db.Decimal(5, 2)\n  expiryDate   DateTime?\n  lotNumber    String?\n  notes        String?\n  createdAt    DateTime  @default(now())\n\n  entry     StockEntry  @relation(fields: [entryId], references: [id], onDelete: Cascade)\n  stockItem StockItem   @relation(fields: [stockItemId], references: [id])\n  batch     StockBatch? @relation(fields: [batchId], references: [id])\n\n  @@index([entryId])\n  @@index([stockItemId])\n}\n\n// ─────────────────────────────────────────────────────────\n// 8. STOCK EXIT (Saída: Consumo / Venda / Perda / Ajuste-)\n// ─────────────────────────────────────────────────────────\nmodel StockExit {\n  id              String          @id @default(ulid())\n  establishmentId String\n  type            StockExitType\n  status          StockExitStatus @default(DRAFT)\n  reference       String?\n  exitDate        DateTime        @default(now())\n  reason          String?\n  totalAmount     Decimal?        @db.Decimal(10, 2)\n  notes           String?\n  createdBy       String?\n  approvedBy      String?\n  approvedAt      DateTime?\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @updatedAt\n\n  establishment Establishment   @relation(fields: [establishmentId], references: [id])\n  items         StockExitItem[]\n  movements     StockMovement[]\n\n  @@index([establishmentId, status])\n  @@index([establishmentId, exitDate])\n  @@index([establishmentId, type])\n}\n\n// ─────────────────────────────────────────────────────────\n// 9. STOCK EXIT ITEM (Linha de Saída)\n// ─────────────────────────────────────────────────────────\nmodel StockExitItem {\n  id          String   @id @default(ulid())\n  exitId      String\n  stockItemId String\n  batchId     String?\n  quantity    Float\n  unitCost    Decimal? @db.Decimal(10, 4)\n  totalCost   Decimal? @db.Decimal(10, 4)\n  notes       String?\n  createdAt   DateTime @default(now())\n\n  exit      StockExit   @relation(fields: [exitId], references: [id], onDelete: Cascade)\n  stockItem StockItem   @relation(fields: [stockItemId], references: [id])\n  batch     StockBatch? @relation(fields: [batchId], references: [id])\n\n  @@index([exitId])\n  @@index([stockItemId])\n}\n\n// ─────────────────────────────────────────────────────────\n// 10. STOCK MOVEMENT (Livro de Movimentos - Auditoria)\n// ─────────────────────────────────────────────────────────\nmodel StockMovement {\n  id              String            @id @default(ulid())\n  establishmentId String\n  stockItemId     String\n  type            StockMovementType\n  direction       StockMovementDir // IN ou OUT\n  quantity        Float\n  quantityBefore  Float\n  quantityAfter   Float\n  unitCost        Decimal?          @db.Decimal(10, 4)\n  entryId         String?\n  exitId          String?\n  reference       String?\n  notes           String?\n  createdBy       String?\n  createdAt       DateTime          @default(now())\n\n  establishment Establishment @relation(fields: [establishmentId], references: [id])\n  stockItem     StockItem     @relation(fields: [stockItemId], references: [id])\n  entry         StockEntry?   @relation(fields: [entryId], references: [id])\n  exit          StockExit?    @relation(fields: [exitId], references: [id])\n\n  @@index([establishmentId, stockItemId])\n  @@index([establishmentId, createdAt])\n  @@index([establishmentId, type])\n}\n\n// ─────────────────────────────────────────────────────────\n// 11. STOCK ALERT (Alertas Automáticos)\n// ─────────────────────────────────────────────────────────\nmodel StockAlert {\n  id              String           @id @default(ulid())\n  establishmentId String\n  stockItemId     String\n  type            StockAlertType\n  status          StockAlertStatus @default(ACTIVE)\n  message         String\n  threshold       Float?\n  currentValue    Float?\n  resolvedAt      DateTime?\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  establishment Establishment @relation(fields: [establishmentId], references: [id])\n  stockItem     StockItem     @relation(fields: [stockItemId], references: [id])\n\n  @@index([establishmentId, status])\n  @@index([establishmentId, type])\n}\n\n// ─────────────────────────────────────────────────────────\n// 12. STOCK INVENTORY COUNT (Contagem Física / Inventário)\n// ─────────────────────────────────────────────────────────\nmodel StockInventoryCount {\n  id              String               @id @default(ulid())\n  establishmentId String\n  name            String\n  status          StockInventoryStatus @default(DRAFT)\n  startedAt       DateTime?\n  completedAt     DateTime?\n  notes           String?\n  createdBy       String?\n  createdAt       DateTime             @default(now())\n  updatedAt       DateTime             @updatedAt\n\n  establishment Establishment             @relation(fields: [establishmentId], references: [id])\n  items         StockInventoryCountItem[]\n\n  @@index([establishmentId, status])\n}\n\nmodel StockInventoryCountItem {\n  id          String    @id @default(ulid())\n  inventoryId String\n  stockItemId String\n  expectedQty Float // quantidade no sistema antes da contagem\n  countedQty  Float? // quantidade contada fisicamente\n  difference  Float? // diferença (contada - esperada)\n  unitCost    Decimal?  @db.Decimal(10, 4)\n  notes       String?\n  countedAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  inventory StockInventoryCount @relation(fields: [inventoryId], references: [id], onDelete: Cascade)\n  stockItem StockItem           @relation(fields: [stockItemId], references: [id])\n\n  @@unique([inventoryId, stockItemId])\n  @@index([inventoryId])\n}\n\nmodel Subscription {\n  id                   String             @id @default(ulid())\n  establishmentId      String             @unique\n  stripeSubscriptionId String             @unique\n  planCycleId          String\n  status               SubscriptionStatus @default(TRIALING)\n  currentPeriodStart   DateTime?\n  currentPeriodEnd     DateTime?\n  cancelAtPeriodEnd    Boolean\n  cancelAt             DateTime?\n  canceledAt           DateTime?\n  stripeCustomerId     String             @unique\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n  cancellationComment  String?\n  cancellationFeedback String?\n  cancellationReason   String?\n  endedAt              DateTime?\n  trialEnd             DateTime?\n  establishment        Establishment      @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n  planCycle            PlanCycle          @relation(fields: [planCycleId], references: [id])\n\n  @@index([stripeCustomerId])\n  @@index([establishmentId])\n  @@index([status])\n  @@index([stripeCustomerId, status])\n}\n\nmodel Plan {\n  id         String        @id @default(ulid())\n  name       String\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt\n  planCycles PlanCycle[]\n  features   PlanFeature[]\n}\n\nmodel PlanCycle {\n  id           String         @id @default(ulid())\n  planId       String\n  cycle        BillingCycle\n  price        Decimal        @db.Decimal(10, 2)\n  priceId      String         @unique\n  createdAt    DateTime       @default(now())\n  updatedAt    DateTime       @updatedAt\n  plan         Plan           @relation(fields: [planId], references: [id], onDelete: Cascade)\n  Subscription Subscription[]\n\n  @@unique([planId, cycle])\n}\n\nmodel Feature {\n  id           String        @id @default(ulid())\n  name         String        @unique\n  type         FeatureType\n  showInPlans  Boolean       @default(true)\n  planFeatures PlanFeature[]\n}\n\nmodel PlanFeature {\n  id            String   @id @default(ulid())\n  planId        String\n  featureId     String\n  valueBoolean  Boolean?\n  valueQuantity Int?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n  feature       Feature  @relation(fields: [featureId], references: [id], onDelete: Cascade)\n  plan          Plan     @relation(fields: [planId], references: [id], onDelete: Cascade)\n\n  @@unique([planId, featureId])\n  @@index([featureId])\n}\n\nmodel Invoice {\n  id              String        @id @default(ulid())\n  customerId      String\n  establishmentId String\n  stripeInvoiceId String\n  subscriptionId  String\n  amountPaid      Int\n  status          String\n  createdAt       DateTime      @default(now())\n  establishment   Establishment @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n}\n\nmodel TaxTable {\n  id          String  @id @default(ulid())\n  countryCode String\n  region      String?\n  name        String\n  rate        Decimal @db.Decimal(5, 2)\n  fiscalCode  String\n  items       Item[]\n\n  @@unique([countryCode, region, fiscalCode])\n  @@index([countryCode])\n}\n\nmodel Theme {\n  id                   String          @id @default(ulid())\n  name                 String\n  config               Json\n  isDefault            Boolean         @default(false)\n  establishmentId      String?\n  activeEstablishments Establishment[] @relation(\"ActiveTheme\")\n  establishment        Establishment?  @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n}\n\nmodel User {\n  id             String          @id @default(ulid())\n  clerkUserId    String          @unique\n  email          String          @unique\n  firstName      String\n  lastName       String\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n  bookings       Booking[]\n  establishments Establishment[]\n}\n\nmodel WebhookEvent {\n  id          String   @id @default(ulid())\n  provider    String\n  eventId     String\n  eventType   String\n  status      String\n  retryCount  Int      @default(0)\n  lastError   String?\n  requestId   String?  @unique // Para distribuída race condition protection\n  processedAt DateTime\n  expiresAt   DateTime\n  createdAt   DateTime @default(now())\n\n  @@unique([provider, eventId])\n  @@index([provider])\n  @@index([status])\n  @@index([expiresAt])\n  @@index([requestId])\n}\n\nmodel ServiceZone {\n  id              String         @id @default(ulid())\n  name            String\n  isActive        Boolean        @default(true)\n  position        Int            @default(0)\n  establishmentId String\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n  servicePoints   ServicePoint[]\n  establishment   Establishment  @relation(fields: [establishmentId], references: [id], onDelete: Cascade)\n\n  @@index([establishmentId])\n}\n\nmodel ServicePoint {\n  id           String           @id @default(ulid())\n  name         String\n  type         ServicePointType @default(TABLE)\n  maxCapacity  Int              @default(4)\n  minCapacity  Int              @default(1)\n  isReservable Boolean          @default(true)\n  isPriority   Boolean          @default(false)\n  isActive     Boolean          @default(true)\n  token        String?          @unique @default(ulid())\n  zoneId       String\n  createdAt    DateTime         @default(now())\n  updatedAt    DateTime         @updatedAt\n  color        String           @default(\"gray\")\n  height       Float            @default(1)\n  rotation     Float            @default(0)\n  shape        String           @default(\"rectangle\")\n  width        Float            @default(1)\n  x            Float            @default(0)\n  y            Float            @default(0)\n  z            Float            @default(0)\n  qrCodes      QrCode[]\n  zone         ServiceZone      @relation(fields: [zoneId], references: [id], onDelete: Cascade)\n\n  @@index([zoneId])\n}\n"
}

